import {at,distinctValues,pageItems,bindArguments,template} from '/collection-model.js';
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
const button=(text,click)=>{const b=el('button',text);b.type='button';b.onclick=click;return b;};let id=0;
export function collectionSurface(items,definition,invoke){
 const root=el('div',undefined,'collection-browser');root.setAttribute('role','region');root.setAttribute('aria-label',definition.title);
 const controls=el('div',undefined,'collection-filters'),states=new Map();let page=1,size=definition.pagination?.defaultSize;
 const field=(caption,control)=>{const n=el('div',undefined,'collection-filter'),label=el('label',caption);control.id='collection-control-'+(++id);label.htmlFor=control.id;n.append(label,control);controls.append(n);};
 const values=()=>Object.fromEntries([...states].map(([key,s])=>[key,s.read()]));
 function changed(selected){for(const rule of definition.filterExclusions||[]){const toggle=states.get(rule.toggle),select=states.get(rule.select);if(!toggle||!select)throw Error('Declared filter exclusion references an unknown control');if(selected===rule.select&&select.read()===rule.value)toggle.control.checked=false;if(selected===rule.toggle&&toggle.read()&&select.read()===rule.value)select.control.value='';}page=1;paint();}
 for(const spec of definition.filters||[]){let control,read;if(spec.kind==='toggle'){control=el('input');control.type='checkbox';control.checked=spec.default===true;const label=el('label',undefined,'collection-toggle');label.append(control,el('span',spec.label));controls.append(label);read=()=>control.checked;}
  else if(spec.kind==='select'){control=el('select');const empty=el('option',spec.emptyLabel);empty.value='';control.append(empty);if(spec.options!=='distinct-values')throw Error('Unsupported declared select options');const choices=distinctValues(items,spec.path);choices.forEach((value,index)=>{const o=el('option',String(value));o.value=String(index);control.append(o);});const selected=choices.findIndex(v=>v===spec.default);control.value=selected<0?'':String(selected);read=()=>control.value===''?'':choices[Number(control.value)];field(spec.label,control);}
  else if(spec.kind==='search'){control=el('input');control.type='search';control.value=spec.default??'';control.placeholder=spec.placeholder||'';read=()=>control.value.trim();field(spec.label,control);}
  else throw Error('Unsupported declared filter kind: '+spec.kind);states.set(spec.id,{control,read});control.addEventListener(spec.kind==='search'?'input':'change',()=>changed(spec.id));
 }
 if(definition.pagination){const select=el('select');for(const value of definition.pagination.sizes){const o=el('option',String(value));o.value=value;select.append(o);}select.value=size;select.onchange=()=>{size=Number(select.value);page=1;paint();};field(definition.pagination.label,select);}
 const summary=el('p',undefined,'collection-count');summary.setAttribute('role','status');const list=el('div',undefined,'items collection-items'),pager=el('nav',undefined,'collection-pages');pager.setAttribute('aria-label',definition.title+' pages');
 const pageLabel=el('span');let previous,next;if(definition.pagination){previous=button(definition.pagination.previous,()=>move(-1));next=button(definition.pagination.next,()=>move(1));pager.append(previous,pageLabel,next);}
 function move(delta){page+=delta;paint();list.scrollIntoView({block:'start'});}
 function paint(){const result=pageItems(items,definition,values(),page,size);page=result.page;summary.textContent=definition.countTemplate?template(result.filtered?definition.countTemplate:definition.emptyTemplate,result):String(result.filtered);if(definition.pagination){pageLabel.textContent=template(definition.pagination.pageTemplate,result);previous.disabled=page===1;next.disabled=page===result.pages;}list.replaceChildren();for(const item of result.items){const row=el('div',undefined,'item collection-item');row.append(el('strong',String(at(item,definition.itemLabel)??'')));const description=(definition.itemSummary||[]).map(path=>at(item,path)).filter(v=>v!==undefined&&v!==null).join(' · ');if(description)row.append(el('small',description));for(const action of definition.actions||[]){const b=button(action.label,()=>invoke(action.tool,bindArguments(action.arguments,item)));b.className='quiet';b.setAttribute('aria-label',action.label+' · '+String(at(item,definition.itemLabel)??''));row.append(b);}list.append(row);}}
 if(controls.childNodes.length)root.append(controls);root.append(summary);for(const action of definition.actions||[])if(action.description)root.append(el('p',action.description,'collection-explanation'));root.append(list);if(definition.pagination)root.append(pager);paint();return root;
}
